<script setup lang="ts">
import {ref,reactive,onMounted,computed} from 'vue'
import {Users,Settings2,Music2,Bell,Trophy,Download,Save,Plus,ArrowLeft,Check,ExternalLink} from 'lucide-vue-next'
import InviteManager from './InviteManager.vue'
import {db,fail,friendly} from '../lib/supabase'
import {user,isAdmin,authReady} from '../lib/session'
import {defaults,type Settings,type Profile,type Invitation,type Rsvp,type Song,type Announcement} from '../lib/types'
const props=defineProps<{settings:Settings}>(),emit=defineEmits<{home:[];login:[];updated:[value:Settings]}>()
const tab=ref('guests'),busy=ref(false),error=ref(''),message=ref(''),search=ref(''),profiles=ref<Profile[]>([]),invitations=ref<Invitation[]>([]),rsvps=ref<Rsvp[]>([]),songs=ref<Song[]>([]),announcements=ref<Announcement[]>([]),contacts=ref<{id:string;email:string}[]>([]),runs=ref<{user_id:string;xp:number;care_count:number;coins:number;hidden:boolean}[]>([])
const settings=reactive<Settings>(JSON.parse(JSON.stringify({...defaults,...props.settings}))),notice=reactive({title:'',body:''})
const filtered=computed(()=>profiles.value.filter(p=>(p.full_name+' '+p.alias).toLowerCase().includes(search.value.toLowerCase())))
const attending=computed(()=>rsvps.value.filter(r=>r.attending).reduce((n,r)=>n+r.guests,0))
const inv=(id:string)=>invitations.value.find(i=>i.user_id===id)
const response=(id:string)=>rsvps.value.find(r=>r.user_id===id)
const person=(id:string)=>profiles.value.find(p=>p.id===id)?.full_name??'Invitado'
const contact=(id:string)=>contacts.value.find(c=>c.id===id)?.email??''
async function action(fn:()=>Promise<void>){busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=friendly(e)}finally{busy.value=false}}
async function load(){if(!isAdmin.value)return;const results=await Promise.all([db.from('wedding_profiles').select('*').order('created_at',{ascending:false}),db.from('wedding_invitations').select('*'),db.from('wedding_rsvps').select('*'),db.from('wedding_songs').select('*').order('created_at',{ascending:false}),db.from('wedding_announcements').select('*').order('created_at',{ascending:false}),db.from('wedding_pets').select('user_id,xp,care_count,coins,hidden').order('xp',{ascending:false}).limit(100),db.rpc('wedding_guest_contacts')]);for(const r of results)fail(r.error);profiles.value=results[0].data??[];invitations.value=results[1].data??[];rsvps.value=results[2].data??[];songs.value=results[3].data??[];announcements.value=results[4].data??[];runs.value=results[5].data??[];contacts.value=results[6].data??[]}
async function approve(id:string,approved:boolean,max:number){await action(async()=>{const {error:e}=await db.from('wedding_invitations').upsert({user_id:id,approved,max_guests:max});fail(e);await load();message.value='Invitación actualizada.'})}
async function saveSettings(){await action(async()=>{if(settings.date&&!Number.isFinite(Date.parse(settings.date)))throw new Error('La fecha no es válida. Usa formato ISO con zona horaria.');if(settings.rsvp_deadline&&!Number.isFinite(Date.parse(settings.rsvp_deadline)))throw new Error('El plazo no es válido.');if(settings.spotify_playlist&&!/^https:\/\/open\.spotify\.com\/playlist\/[A-Za-z0-9]+(?:\?.*)?$/.test(settings.spotify_playlist))throw new Error('Usa un enlace de playlist de Spotify.');const {error:e}=await db.from('wedding_settings').update({content:settings,updated_at:new Date().toISOString()}).eq('id',1);fail(e);emit('updated',JSON.parse(JSON.stringify(settings)));message.value='Cambios guardados en la web.'})}
async function status(id:string,value:string){await action(async()=>{const {error:e}=await db.from('wedding_songs').update({status:value}).eq('id',id);fail(e);await load();message.value='Estado de la canción actualizado.'})}
async function addNotice(){await action(async()=>{const {error:e}=await db.from('wedding_announcements').insert({title:notice.title.trim(),body:notice.body.trim(),published:false});fail(e);notice.title='';notice.body='';await load();message.value='Borrador guardado.'})}
async function publish(a:Announcement){await action(async()=>{const {error:e}=await db.from('wedding_announcements').update({published:!a.published}).eq('id',a.id);fail(e);await load();message.value=a.published?'Aviso retirado.':'Aviso publicado en el área de invitados.'})}
function csvCell(v:unknown){let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
function exportCsv(consentingOnly=false){const rows=profiles.value.filter(p=>!consentingOnly||p.email_updates).map(p=>{const r=response(p.id);return [p.full_name,p.alias,contact(p.id),p.phone,p.email_updates?'Sí':'No',r?r.attending?'Sí':'No':'Pendiente',r?.guests??'',r?.guest_names??'',r?.dietary??'',r?.bus?'Sí':'No']});const csv=[['Nombre','Alias','Correo','Teléfono','Avisos por correo','Asistencia','Personas','Asistentes','Menú','Transporte'],...rows].map(row=>row.map(csvCell).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=consentingOnly?'invitados-con-avisos.csv':'invitados-boda.csv';a.click();URL.revokeObjectURL(url)}
async function moderate(id:string,hidden:boolean){await action(async()=>{const {error:e}=await db.from('wedding_pets').update({hidden}).eq('user_id',id);fail(e);await load();message.value='Clasificación actualizada.'})}
onMounted(()=>{void action(load)})
</script>
<template><main class="admin-shell"><header class="admin-top"><button class="text-link" @click="emit('home')"><ArrowLeft :size="18"/> Volver a la boda</button><span class="brand">L <i>&</i> J</span><span class="small">EL RINCÓN DE LOS NOVIOS</span></header><div v-if="!authReady" class="empty-state">Comprobando acceso…</div><div v-else-if="!user" class="empty-state"><h1>El rincón de los novios</h1><p>Inicia sesión con una cuenta autorizada para gestionar la boda.</p><button class="btn" @click="emit('login')">Entrar</button></div><div v-else-if="!isAdmin" class="empty-state"><h1>Este rincón es privado</h1><p>Tu cuenta no tiene acceso de administrador. Puedes seguir disfrutando de la invitación.</p><button class="btn" @click="emit('home')">Volver a la boda</button></div><template v-else><div class="admin-title"><div><span class="eyebrow">LAURA Y JAVIER</span><h1>Todo para vuestro día</h1><p>Los pequeños detalles, en un mismo lugar.</p></div><button class="btn secondary" @click="action(load)" :disabled="busy">Actualizar datos</button></div><div class="stats-grid"><div><span>Registrados</span><strong>{{profiles.length}}</strong></div><div><span>Personas confirmadas</span><strong>{{attending}}</strong></div><div><span>Respuestas pendientes</span><strong>{{profiles.length-rsvps.length}}</strong></div><div><span>Canciones propuestas</span><strong>{{songs.length}}</strong></div></div><nav class="admin-tabs"><button v-for="item in [{id:'guests',label:'Invitados',icon:Users},{id:'settings',label:'La web',icon:Settings2},{id:'songs',label:'Música',icon:Music2},{id:'notices',label:'Avisos',icon:Bell},{id:'scores',label:'Perritos',icon:Trophy}]" :key="item.id" :class="{active:tab===item.id}" @click="tab=item.id"><component :is="item.icon" :size="18"/>{{item.label}}</button></nav><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" class="success" role="status">{{message}}</p><section class="admin-content" v-if="tab==='guests'"><InviteManager/><h2>Usuarios que ya han activado su cuenta</h2><div class="toolbar"><input v-model="search" placeholder="Buscar por nombre o alias" aria-label="Buscar invitados"/><button class="btn secondary" @click="exportCsv()"><Download :size="16"/> Exportar CSV</button></div><p class="small muted">Las nuevas invitaciones se habilitan con su cupo al activar la cuenta. Aquí puedes ajustar el cupo y la asistencia.</p><p v-if="!filtered.length" class="empty-state">Los invitados aparecerán aquí cuando activen su postal y completen su perfil.</p><article v-for="p in filtered" :key="p.id" class="guest-admin-row"><div><h3>{{p.full_name}}</h3><p>{{contact(p.id)}} <span v-if="p.phone">· {{p.phone}}</span></p><small>Alias: {{p.alias}} · Correo: {{p.email_updates?'con consentimiento':'sin avisos'}}</small><p v-if="response(p.id)"><b>{{response(p.id)?.attending?'Asiste':'No asiste'}}</b> · {{response(p.id)?.guests}} personas<br/>{{response(p.id)?.guest_names}}<br/><span v-if="response(p.id)?.dietary">Menú: {{response(p.id)?.dietary}}</span><br v-if="response(p.id)?.dietary"/>Transporte: {{response(p.id)?.bus?'Le interesa':'No solicitado'}}</p></div><div class="invite-actions"><label>Cupo<select :value="inv(p.id)?.max_guests??1" @change="approve(p.id,inv(p.id)?.approved??false,Number(($event.target as HTMLSelectElement).value))" :disabled="busy"><option v-for="n in 10" :value="n" :key="n">{{n}}</option></select></label><button class="btn" :class="{'secondary':inv(p.id)?.approved}" :disabled="busy" @click="approve(p.id,!inv(p.id)?.approved,inv(p.id)?.max_guests??1)">{{inv(p.id)?.approved?'Deshabilitar':'Habilitar invitación'}}</button></div></article></section><form v-else-if="tab==='settings'" class="admin-content form-grid" @submit.prevent="saveSettings"><h2 class="full-width">Lo que cuenta vuestra web</h2><label>Nombres<input v-model="settings.couple" required/></label><label>Nombre del perrito<input v-model="settings.dog_name" required/></label><label>Fecha y hora con zona horaria<input v-model="settings.date" placeholder="2027-06-12T18:00:00+02:00"/><small>Usa +01:00 o +02:00 según el horario de Madrid.</small></label><label>Lugar de la boda<input v-model="settings.location" placeholder="Municipio o finca"/></label><label class="full-width">Bienvenida<textarea v-model="settings.welcome" required/></label><label>Ceremonia<input v-model="settings.ceremony_name"/></label><label>Hora de la ceremonia<input v-model="settings.ceremony_time" type="time"/></label><label class="full-width">Dirección de la ceremonia<input v-model="settings.ceremony_address"/></label><label>Celebración<input v-model="settings.reception_name"/></label><label>Hora de la celebración<input v-model="settings.reception_time" type="time"/></label><label class="full-width">Dirección de la celebración<input v-model="settings.reception_address"/></label><label>Plazo de asistencia con zona horaria<input v-model="settings.rsvp_deadline" placeholder="2027-05-15T23:59:00+02:00"/></label><label>Playlist de Spotify<input v-model="settings.spotify_playlist" type="url"/></label><label>Transporte<textarea v-model="settings.transport"/></label><label>Alojamiento<textarea v-model="settings.accommodation"/></label><label>Vestimenta<textarea v-model="settings.dress_code"/></label><label>Contacto que se mostrará en la web<textarea v-model="settings.contact"/></label><h3 class="full-width">Vuestra historia</h3><div v-for="(s,i) in settings.story" :key="i" class="full-width editor-row"><label>Título<input v-model="s.title" required/></label><label>Recuerdo<textarea v-model="s.text" required/></label><label>Fotografía<select v-model="s.image"><option value="couple">Pareja</option><option value="home">Hogar</option><option value="dog">Perrito</option></select></label><button type="button" class="text-link" @click="settings.story.splice(i,1)">Quitar recuerdo</button></div><button type="button" class="text-link full-width" @click="settings.story.push({title:'',text:'',image:'couple'})"><Plus :size="16"/> Añadir recuerdo</button><h3 class="full-width">Programa del día</h3><div v-for="(s,i) in settings.schedule" :key="i" class="full-width schedule-editor"><input v-model="s.title" aria-label="Momento del día" required/><input v-model="s.time" type="time" aria-label="Hora"/></div><button class="btn" :disabled="busy"><Save :size="17"/>{{busy?'Guardando…':'Guardar cambios'}}</button></form><section v-else-if="tab==='songs'" class="admin-content"><h2>La música de la fiesta</h2><p>Revisa las propuestas y añádelas a vuestra playlist en Spotify. Marca «Añadida» después de incorporarla.</p><p class="notice">La sincronización automática necesita una aplicación de Spotify y su autorización. Por ahora, las propuestas y la revisión se guardan aquí; el alta en Spotify es manual.</p><a v-if="settings.spotify_playlist" class="btn secondary" :href="settings.spotify_playlist" target="_blank" rel="noopener noreferrer">Abrir playlist <ExternalLink :size="16"/></a><p v-if="!songs.length" class="empty-state">Todavía no hay propuestas.</p><div v-for="s in songs" :key="s.id" class="song-row"><div><b>{{s.title}}</b><p>{{s.artist}} · {{person(s.user_id)}}</p><a v-if="s.spotify_url" :href="s.spotify_url" target="_blank" rel="noopener noreferrer" class="text-link">Abrir canción <ExternalLink :size="14"/></a></div><select :value="s.status" @change="status(s.id,($event.target as HTMLSelectElement).value)" :disabled="busy" aria-label="Estado de la canción"><option value="pending">Pendiente</option><option value="approved">Aprobada</option><option value="added">Añadida a Spotify</option><option value="rejected">No seleccionada</option></select></div></section><section v-else-if="tab==='notices'" class="admin-content"><h2>Avisos para los invitados</h2><p>Publica novedades en su área privada. Solo las ven las cuentas que tienen activados los avisos dentro de la web.</p><form @submit.prevent="addNotice"><label>Título<input v-model="notice.title" maxlength="120" required/></label><label>Mensaje<textarea v-model="notice.body" maxlength="3000" required rows="4"/></label><button class="btn" :disabled="busy"><Save :size="16"/> Guardar borrador</button></form><article v-for="a in announcements" :key="a.id" class="announcement"><span class="badge">{{a.published?'Publicado':'Borrador'}}</span><h3>{{a.title}}</h3><p class="preserve">{{a.body}}</p><button class="btn secondary" :disabled="busy" @click="publish(a)">{{a.published?'Retirar aviso':'Publicar en la web'}}</button></article><h3>Avisos por correo</h3><p class="small">El envío por correo necesita configurar un proveedor de email. Ya se guarda el consentimiento y puedes exportar únicamente a quienes quieren recibirlos.</p><button class="btn secondary" @click="exportCsv(true)"><Download :size="16"/> Exportar contactos con consentimiento</button></section><section v-else class="admin-content"><h2>Los cuidadores del perrito</h2><p>Las monedas y la experiencia se calculan en el servidor. Puedes moderar la clasificación de cuidadores sin borrar su mascota.</p><p v-if="!runs.length" class="empty-state">Todavía no hay mascotas guardadas.</p><div v-for="r in runs" :key="r.user_id" class="song-row"><div><b>{{person(r.user_id)}}</b><p>{{r.xp}} XP · {{r.care_count}} cuidados · {{r.coins}} monedas</p></div><button class="btn secondary" @click="moderate(r.user_id,!r.hidden)" :disabled="busy">{{r.hidden?'Mostrar':'Ocultar'}}</button></div></section></template></main></template>
